1383			&\approx_{\delta_{\mG}} \sum_{g \in \mathcal{G}} \bra{\hat{\psi}} (\hat{S}_g)_{\alice \alice'} \ket{\hat{\psi}} \label{eq:qld-s-good-g}\\
1384	                  &\approx_{(\delta_Q)^{1/2}} \E_{x,z,\alpha,\beta} \sum_{g_\xpt, g_\zpt}\bra{\hat{\psi}}  (\hat{S}_{g_\xpt,g_\zpt})_{\alice \alice'} \otimes \Big ( \sum_{b,b'} 1_{\alpha b + \beta b' = \alpha g_\xpt (x) + \beta g_\zpt(z)} \, \hat{M}^{(\Point,Z),z}_{b'} \hat{M}^{(\Point,X),x}_{b} \Big)_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-s-mm}\\
1385	                  &\approx _{(\delta_Q)^{1/2}} \E_{x,z,\alpha,\beta} \sum_{g_\xpt, g_\zpt}\bra{\hat{\psi}}  (\hat{S}_{g_\xpt,g_\zpt})_{\alice \alice'} \otimes \Big ( \sum_{b,b', b''} 1_{\alpha b + \beta b' = \alpha g_\xpt (x) + \beta g_\zpt(z) = \alpha b'' + \beta b'} \cdot\, \notag \\
1386	          &\hspace{12em} \hat{M}^{(\Point, X), x}_{b''} \hat{M}^{(\Point,Z),z}_{b'} \hat{M}^{(\Point,X),x}_{b} \Big)_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-s-mmm} \\
1387	      &\approx _{1/q} \E_{x,z,\alpha,\beta} \sum_{g_\xpt, g_\zpt}\bra{\hat{\psi}}  (\hat{S}_{g_\xpt,g_\zpt})_{\alice \alice'} \otimes \Big ( \sum_{b,b'} 1_{\alpha b + \beta b' = \alpha g_\xpt (x) + \beta g_\zpt(z) } \cdot \,\notag\\
1388	    &\hspace{12em}\hat{M}^{(\Point, X), x}_{b} \hat{M}^{(\Point,Z),z}_{b'} \hat{M}^{(\Point,X),x}_{b} \Big)_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-s-mmm-positive} \\
1389			&\approx_{ 1/q}\E_{x,z}  \sum_{g_\xpt, g_\zpt} \bra{\hat{\psi}} (\hat{S}_{g_\xpt,g_\zpt})_{\alice \alice'} \otimes \Big ( \hat{M}^{(\Point, X), x}_{g_\xpt(x)} \hat{M}^{(\Point,Z),z}_{g_\zpt(z)} \hat{M}^{(\Point,X),x}_{g_\xpt(x)} \Big)_{\bob \alice''} \ket{\hat{\psi}}. \label{eq:qld-xzx-disagree}
