1392	        \begin{align*}
1393	          &\Big| \E_{x,z,\alpha,\beta} \sum_{g_\xpt, g_\zpt} \bra{\hat{\psi}} \Big( (\hat{S}_{g_\xpt, g_\zpt})_{\alice \alice'} \cdot (I -  \Big( \sum_{b,b'} 1_{\alpha b + \beta b' = \alpha g_\xpt (x) + \beta g_\zpt(z)} \, \hat{M}^{(\Point,Z),z}_{b'} \hat{M}^{(\Point,X),x}_{b} \Big)_{\bob \alice''}\Big) \ket{\hat{\psi}} \Big| \\
1394	          \leq& \sqrt{\E_{x,z,\alpha,\beta} \sum_{g_\xpt, g_\zpt} \bra{\hat{\psi}} (\hat{S}_{g_\xpt, g_\zpt})_{\alice \alice'}^2 \ket{\hat{\psi}}} \\
1395	          &\quad \cdot \sqrt{\E_{x,z,\alpha,\beta} \sum_{g_\xpt, g_\zpt} \norm{ (\hat{S}_{g_\xpt, g_\zpt})_{\alice \alice'} \ot 
1396	\Big(I - \Big( \sum_{b,b'} 1_{\alpha b + \beta b' = \alpha g_\xpt(x) + \beta g_\zpt(z)} \, \hat{M}^{(\Point, Z),z}_{b'} \hat{M}^{(\Point, X), x}_{b} \Big)_{\bob \alice''} \Big)\ket{\hat{\psi}} }^2 } \\
1397	          \leq& 1 \cdot \sqrt{\delta_Q}.
1398	        \end{align*}
1399	        \Cref{eq:qld-s-mmm} follows by a similar calculation\anote{TODO}. To pass from here to \Cref{eq:qld-s-mmm-positive}, we argue that for $\alpha \neq 0$, the indicator forces $b = b''$, and the terms where $\alpha = 0$ are bounded in absolute value by $1/q$. Finally, to reach \Cref{eq:qld-xzx-disagree}, we apply \Cref{eq:qld-g-separable} to the expectation of the indicator over $\alpha, \beta$. \Cref{eq:qld-xzx-disagree} tells us that
1400	        \begin{equation} \big(\hat{S}_{[\eval_{x}(\cdot) = a, \eval_{z}(\cdot) = b]}\big)_{\alice \alice'} \simeq_{O(\delta_{\mG} + (\delta_Q)^{1/2} + 1/q)} \big( \hat{M}^{(\Point, X), x}_{a} \hat{M}^{(\Point, Z), z}_{b} \hat{M}^{(\Point, X), x}_{a}\big)_{\bob \alice''}. \label{eq:qld-sgg-mhat-sandwich} \end{equation}
