429	
430	The combined point and line measurements of the previous two sections are next
431	merged into a single measurement returning a pair of global polynomials that
432	encode the $X$-basis and the $Z$-basis information simultaneously. This is
433	done by encoding the pair as one polynomial in $2m+2$ variables and invoking
434	the quantum soundness of the classical low individual degree test
435	(Theorem~\ref{lem:ld-soundness}). The classical game, its question
436	distribution, and the line-point distribution are defined at dimension $2m+2$
437	only when $2m+2$ divides $q$ (Definition~\ref{def:ld-game}), a condition that
438	admissibility of $(q,m,d)$ does not supply; the statements below are the
439	source statements, without that condition, and their proofs are blocked at
440	the instantiation step for admissible parameters with $m \ge 2$. The
441	obstruction is recorded in Remark~\ref{rem:qld-4-7-divisibility} and
442	analyzed, together with candidate repairs, in
443	\cite{gap:qpbt_ld-dimension-divisibility}.
444	
445	\begin{definition}[The combining map]
446		\label{def:combine-map}
447		\uses{def:polyfunc, def:line}
448		For $f, g \in \mathrm{ideg}_{d,m}(\F_q)$, the polynomial
449		$\mathrm{combine}_{f,g} \in \mathrm{ideg}_{d,2m+2}(\F_q)$ is defined by
450		\[
451			\mathrm{combine}_{f,g}(x, z, \alpha, \beta)
452			= \alpha f(x) + \beta g(z)\,,
453			\qquad x \in \F_q^m,\ z \in \F_q^m,\ \alpha \in \F_q,\
454			\beta \in \F_q\,.
455		\]
456		The combining map is also defined for polynomials restricted to lines.
457		Let $\ell$ be a line in $\F_q^{2m+2}$ with intercept
458		$u = (u_X, u_Z, u_\alpha, u_\beta)$ and slope
459		$v = (v_X, v_Z, v_\alpha, v_\beta)$, and let $\ell_X$ and $\ell_Z$ be
460		lines in $\F_q^m$ such that for every point
461		$(x, z, \alpha, \beta) \in \ell$ it holds that $x \in \ell_X$ and
462		$z \in \ell_Z$. Then for any two polynomials
463		$f \in \deg_{md}(\ell_X)$ and $g \in \deg_{md}(\ell_Z)$, the polynomial
464		$\mathrm{combine}_{f,g} \in \deg_{md+1}(\ell)$ is defined by
465		\begin{equation}
466			\label{eq:combine-lines}
467			\mathrm{combine}_{f,g}(u + t \cdot v)
468			= (u_\alpha + t \cdot v_\alpha)\, f(u_X + t \cdot v_X)
469			+ (u_\beta + t \cdot v_\beta)\, g(u_Z + t \cdot v_Z)\,,
470			\qquad t \in \F_q\,.
471		\end{equation}
472		The degree bound holds because $f$ and $g$, restricted to lines, are
473		polynomials of degree at most $md$ in the line parameter, and each is
474		multiplied by an affine factor of degree at most one.
475	\end{definition}
476	
477	\begin{lemma}[Combined point measurement on the extended coordinates]
478		\label{lem:qld-4-12}
479		\uses{lem:qld-4-10, def:expanded-state, def:expanded-point-measurement,
480			def:povm-distance, def:symmetric-equivalents}
481		For all $x, z \in \F_q^m$, $\alpha, \beta \in \F_q$, and
482		$\hilb \in \{\hilb_{\mathsf{A}}, \hilb_{\mathsf{B}}\}$ there exists a
483		projective measurement
484		$\{\hat{Q}^{x,z,\alpha,\beta}_{c}\}_{c \in \F_q}$ acting on
485		$\hilb \ot (\C^q)^{\ot M}$ such that the following holds, where
486		$\delta_Q$ is the function of Lemma~\ref{lem:qld-4-10}:
487		\begin{enumerate}
488			\item (\textbf{Self-consistency}) On average over uniformly random
489			$(x, z, \alpha, \beta) \in \F_q^{2m+2}$,
490			\begin{equation}
491				\label{eq:qld-4-12-self-cons}
492				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{A}\mathsf{A}'}
493				\approx_{\delta_Q}
494				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{B}\mathsf{A}''}\,.
495			\end{equation}
496			\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly
497			random $(x, z, \alpha, \beta) \in \F_q^{2m+2}$,
498			\begin{gather}
499				\label{eq:qld-4-12-cons-m-hat}
500				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{A}\mathsf{A}'}
501				\approx_{\delta_Q}
502				\Big( \sum_{\substack{a,b:\\ \alpha a + \beta b = c}}
503				\hat{M}^{(\mathrm{Point},X),x}_{a} \,
504				\hat{M}^{(\mathrm{Point},Z),z}_{b}
505				\Big)_{\mathsf{B}\mathsf{A}''}\,, \\
506				\label{eq:qld-4-12-cons-m-hat2}
507				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{A}\mathsf{A}'}
508				\approx_{\delta_Q}
509				\Big( \sum_{\substack{a,b:\\ \alpha a + \beta b = c}}
510				\hat{M}^{(\mathrm{Point},Z),z}_{b} \,
511				\hat{M}^{(\mathrm{Point},X),x}_{a}
512				\Big)_{\mathsf{B}\mathsf{A}''}\,.
513			\end{gather}
514		\end{enumerate}
515		Furthermore, all symmetric equivalents of these approximations also hold.
516	\end{lemma}
517	\begin{proof}
518		\uses{lem:qld-4-10, fact:data-processing}
519		Define
520		$\hat{Q}^{x,z,\alpha,\beta}_{c}
521		= \sum_{a,b \,:\, \alpha a + \beta b = c} \hat{Q}^{x,z}_{a,b}$,
522		a coarse-graining of the projective measurement of
523		Lemma~\ref{lem:qld-4-10}, hence itself projective. A uniformly random
524		point of $\F_q^{2m+2}$ has uniformly random coordinates $(x,z)$, so the
525		self-consistency and consistency properties follow from those of
526		$\{\hat{Q}^{x,z}_{a,b}\}$ established in Lemma~\ref{lem:qld-4-10}
527		together with Lemma~\ref{fact:data-processing}, which shows that
528		coarse-graining the outcomes preserves the $\delta_Q$ bounds.
