561			\big(\hat{Q}^{\ell}
562			_{[\mathrm{eval}_{(x,z,\alpha,\beta)}(\cdot)=a]}
563			\big)_{\mathsf{B}\mathsf{B}'}
564			\simeq_{\delta_{\mathrm{combine}}}
