1211	\begin{proof}
1212	At first we proceed similarly to the proof of Claim~\ref{claim:17-2}, bounding the difference using Cauchy-Schwarz as
1213	\begin{align*}
1214	&\Big| \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{f_X,f_Z} \bra{\hat{\psi}} T^{\line_X, \line_Z}_{f_X, f_Z} \ot  (\Id-\hat{M}^{(\Point,Z),z}_{f_Z(z)}) \ket{\hat{\psi}}\Big|\\
1215	&\leq\Big(\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{f_X, f_Z} \big\| \sqrt{ T^{\line_X, \line_Z}_{f_X, f_Z}} \ot  \Id \ket{\hat{\psi}}\big\|^2 \Big)^{1/2}\\
1216	&\qquad\cdot \Big(\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{f_X, f_Z} \big\| \sqrt{ T^{\line_X, \line_Z}_{f_X, f_Z}} \ot  (\Id-\hat{M}^{(\Point,Z),z}_{f_Z(z)}) \ket{\hat{\psi}}\big\|^2 \Big)^{1/2}\;.
1217	\end{align*}
1218	The first term is at most $1$. The second, as in the proof of Claim~\ref{claim:17-2}, equals
1219	\begin{align}
1220	1-\E_{(\line, \line_X, \line_Z) \sim D} &\E_{(x,z,\alpha, \beta) \in \line} \sum_{b} \bra{\hat{\psi}}  T^{\line_X, \line_Z, z}_{b} \ot \hat{M}^{(\Point,Z),z}_{b} \ket{\hat{\psi}}\notag\\
1221	&=1-\E_{(\line_X,\line_Z)\sim D_{\tvar,i}\times D_{\tvar,j}}
1222	\E_{z\in \line_Z } \sum_{b} \bra{\hat{\psi}}  T^{\line_X, \line_Z, z}_{b}  \ot \hat{M}^{(\Point,Z),z}_{b} \ket{\hat{\psi}}\label{eq:a17-5}\\
1223	&=1-\E_{(\line_X,\line_Z)\sim D_{\tvar,i}\times D_{\tvar,j}}
1224	\E_{z\in \line_Z }\E_{x\in \line_X} \sum_{a,b} \bra{\hat{\psi}}  T^{\line_X, \line_Z}_{[\eval_x(\cdot)=a,\eval_z(\cdot)=b]}  \ot \hat{M}^{(\Point,Z),z}_{b} \ket{\hat{\psi}}\label{eq:a17-6}
1225	\end{align}
1226	where we use the shorthand $T^{\line_X, \line_Z, z}_{b} = \sum_{f_X} T^{\line_X, \line_Z}_{f_X,[\eval_z(\cdot)=b]}$ and $D_{\tvar,i}\times D_{\tvar,j}$ to denote a mixture over all such distributions where $\tvar\in\{\ALine,\DLine\}$ and $i,j\in\{1,\ldots,m\}$. Equality holds in~\eqref{eq:a17-5} because by item 2 of Lemma~\ref{lem:qld-sublines} for $(\ell,\ell_X,\ell_Z)\sim D$ the marginal distribution on $(\ell_X,\ell_Z)$ is a mixture of the product distributions  $D_{\ALine, i}\times D_{\ALine, j}$ and $D_{\DLine, i}\times D_{\DLine,j}$, for $i,j\in \{1,\ldots,m\}$. Moreover, conditioned on $(\ell_X,\ell_Z)$, $z$ is a uniformly random point on $\ell_X$. The last equality in~\eqref{eq:a17-6} holds by definition of 
1227	\begin{align*}
1228	T^{\line_X, \line_Z, z}_{b}&= \sum_{f_X} T^{\line_X, \line_Z}_{f_X,[\eval_z(\cdot)=b]}\\
1229	&= \Es{x \in \line_X} \sum_a \sum_{f_X: f_X(x)=a} T^{\line_X, \line_Z}_{f_X,[\eval_z(\cdot)=b]}\\
1230	&= \Es{x \in \line_X} \sum_a  T^{\line_X, \line_Z}_{[\eval_x(\cdot)=a,\eval_z(\cdot)=b]}\;.
1231	\end{align*}
1232	We next write
1233	\begin{align*}
1234	1-\eqref{eq:a17-6}&\approx_{m(\sqrt{\delta_P}+\sqrt{\delta_Q})}\E_{(\line_X,\line_Z)\sim D_{\tvar,i}\times D_{\tvar,j}}\E_{x\in \line_X} \E_{z\in \line_Z } \sum_{a,b} \bra{\hat{\psi}} \hat{M}^{(\Point,X),x}_{a}\hat{M}^{(\Point,Z),z}_{b}  \ot \hat{M}^{(\Point,Z),z}_{b} \ket{\hat{\psi}} \\
1235	&= \sum_{b} \bra{\hat{\psi}} \hat{M}^{(\Point,Z),z}_{b}  \ot \hat{M}^{(\Point,Z),z}_{b} \ket{\hat{\psi}} \\
1236	&\geq 1-\sqrt{\eps}\;,
1237	\end{align*}
1238	where the first approximation follows from the discussion following Definition~\ref{def:ith-restricted-line} applied to the bounds from Lemma~\ref{lem:qld-sublines} and Lemma~\ref{lem:qld-4-10}, the second line uses that $\{\hat{M}^{(\Point,X),x}_{a}\}$ is a measurement, and the last is by self-consistency of the points measurements (Lemma~\ref{lem:qld-comm-cons}).
1239	\end{proof}
